// 服务端：比对 If-None-Match 与当前 ETag
function serve(reqHeaders, currentETag, content) {
  const inm = reqHeaders['If-None-Match'];
  if (inm && inm === currentETag) {
    return { status: 304, statusText: 'Not Modified', headers: { ETag: currentETag }, body: null };
  }
  return {
    status: 200,
    statusText: 'OK',
    headers: { ETag: currentETag, 'Content-Type': 'text/plain; charset=utf-8' },
    body: content,
  };
}

const show = (label, reqHeaders, etag, content) => {
  const r = serve(reqHeaders, etag, content);
  console.log(label);
  console.log('  请求头: ' + (Object.keys(reqHeaders).length ? JSON.stringify(reqHeaders) : '（无缓存，首次请求）'));
  console.log('  响应  : ' + r.status + ' ' + r.statusText);
  console.log('  响应头: ' + JSON.stringify(r.headers));
  console.log('  主体字节数: ' + (r.body ? Buffer.byteLength(r.body) : 0));
  console.log('');
};

const V1 = 'v1 这是第一版内容，体积较大……';
const etag1 = '"etag-v1"';

show('① 首次请求（客户端无缓存）', {}, etag1, V1);
show('② 再次请求（客户端带上 If-None-Match）', { 'If-None-Match': etag1 }, etag1, V1);
show('③ 内容已更新（服务端 ETag 变化）', { 'If-None-Match': etag1 }, '"etag-v2"', 'v2 这是第二版内容');

console.log('结论：304 没有主体 —— 用「一次往返的开销」换来「不传输大体积内容」。');
console.log('      这就是协商缓存的价值；它适合「内容不常变但必须保证新鲜」的资源（如 HTML 入口）。');
